      L.part('Вал барабана', 'iron', -1.2, 0.9, dz, 0.12, 2.5, 0.12, { round: true, roll: -90 }); L.part('Цепной барабан', 'timber', -0.84, 0.9, dz, 0.88, 1.68, 0.88, { round: true, roll: -90 });
