    const [cx, cz] = D.at(k, plane, t + side * 1.62, 0.08); tile('Кольцо в стене', 'iron', k, plane, t + side * 1.62, 2.3, 0.16, 0.16, 0.07, { sink: 0 }); D.chain(cx, 2.3, cz, R(0.5, 1.2));
    put('Вешка Дома Весов', 'clothRed', cx, 1.72 + J(0.2), cz, 0.07, 0.34, 0.02, { ry: D.FACE[k].ry + J(20), roll: J(8) });
    // Перечёркнутые стрелки: куда вёл проём в прошлые спуски.
