  // --- Перекрытия снизу: архитравы по столпам и колоннам, рёбра от стен, консоли под узкими обходами ---
  const girder = (x1, z1, x2, z2, top, { th = 0.42, w = 0.5, name = 'Архитрав', m = 'stone' } = {}) => put(name, m, (x1 + x2) / 2, top - th, (z1 + z2) / 2, Math.abs(x2 - x1) || w, th, Math.abs(z2 - z1) || w);
