    rib(s * 12, 17.1, s * 12, 21, 5.5); rib(s * 12, 21, s * 12, 27.5, 5.5); if (s > 0) { rib(12, 27.5, 12, 41.7, 5.5); girder(6.4, 34, X, 34, 5.5); }
    // ярус Весов: восточная галерея ствола
