  for (const [a, b] of [[-16.8, -10.4], [-10.4, -3.5], [-3.5, 3.5], [3.5, 10.4], [10.4, 17.1]]) girder(10.4, a, 10.4, b, 11.5);
  rib(10.4, -3.5, 14.4, -3.5, 11.5); girder(-16.8, 10.2, 10.2, 10.2, 11.5, { w: 0.44 }); girder(-13.6, 21.8, 10, 21.8, 11.5, { w: 0.44 });
  for (const x of [-13.6, -6.4, -2.6, 2.6, 6.4]) rib(x, 10.4, x, 21.6, 11.5);
  for (const [a, b] of [[22, 34], [34, 46], [46, ZN]]) girder(6.3, a, 6.3, b, 11.5, { w: 0.44 });
  for (const z of [24.5, 27.5, 31, 38, 49]) rib(6.4, z, X, z, 11.5);
  rib(6.4, 34, X, 34, 11.5); rib(6.4, 41.6, 10, 41.6, 11.5); rib(6.4, 46.4, 10, 46.4, 11.5); girder(-13.8, 22, -13.8, 37.5, 11.5, { w: 0.4 });
  // Цепной мост: тетивы и поперечины снизу, дощатый настил сверху.
