  for (let x = -6.4; x < 5.8; x += 1.55) girder(x, 38, x, 40, 11.5, { th: 0.2, w: 0.18, name: 'Поперечина моста', m: 'timber' });
  D.deck(-6.95, 38.02, 5.95, 39.98, 12, { along: 'x', bw: 0.33, wear: 2.2 });
  // Обход смазчиков: консоль и железный подкос через три метра; под осыпными плитами опор нет.
  const bracket = (k, plane, u, top) => { tile('Консоль обхода', 'stone', k, plane, u, top - 0.85, 0.36, 0.85, 0.55, { sink: 0.02 }); const a = D.at(k, plane, u, 0.05), b = D.at(k, plane, u, 1.85); beam('Подкос обхода', 'iron', [a[0], top - 1.5, a[1]], [b[0], top - 0.06, b[1]], 0.07); };
